def check_row(values, types, domains):
    if type(values) is not list or len(values) != len(types):
        schema_fail()
    out = []
    for val, ftype, dom in zip(values, types, domains):
        if ftype in NUMERIC_TYPES:
            if type(val) is not int or not (dom[0] <= val <= dom[1]):
                schema_fail()
        elif ftype == 'ID':
            if type(val) is not str or val not in dom:
                schema_fail()
        else:
            if type(val) is not bool:
                schema_fail()
        out.append(val)
    return tuple(out)


def parse_traces(arr, types, domains, seen_ids, row_counter):
    if type(arr) is not list:
        schema_fail()
    out = []
    for trace in arr:
        if type(trace) is not dict or set(trace.keys()) != {'id', 'source', 'rows'}:
            schema_fail()
        tid = trace['id']
        src = trace['source']
        if type(tid) is not str or not TRACEID_RE.fullmatch(tid):
            schema_fail()
        if tid in seen_ids:
            schema_fail()
        seen_ids.add(tid)
